{"name": "fws-no media from the guests", "order": 1, "rank": 7, "action": "BLOCK_DROP", "state": "ENABLED", "description": "VyOS firewall name LAN_OUT rule 10 (forward-5.WAN_IN-30>forward-15.LAN_OUT-10)", "locations": [{"id": ${ID_1}}], "srcIps": ["192.168.10.0/24"], "destAddresses": ["192.168.1.30"], "nwServices": [{"id": ${ID_2}}]}
