cat > "$OUT/10.json" <<FWSHIFT_JSON
{"name": "fws-plex to the media box", "order": 2, "rank": 7, "action": "ALLOW", "state": "ENABLED", "description": "VyOS firewall name WAN_IN rule 30, then ipv4 forward filter default-action accept (forward-5.WAN_IN-30)", "locations": [{"id": ${ID_1}}], "destAddresses": ["192.168.1.30"], "nwServices": [{"id": ${ID_2}}]}
