{"name": "fws-old rule", "order": 4, "rank": 7, "action": "ALLOW", "state": "DISABLED", "description": "VyOS firewall name WAN_IN rule 50 (forward-5.WAN_IN-50)", "locations": [{"id": ${ID_1}}], "destAddresses": ["192.168.1.40"], "nwServices": [{"id": ${ID_4}}]}
