cat > "$OUT/13.json" <<FWSHIFT_JSON
{"name": "fws-syn to the mail server", "order": 5, "rank": 7, "action": "ALLOW", "state": "ENABLED", "description": "VyOS firewall name WAN_IN rule 60, then ipv4 forward filter default-action accept (forward-5.WAN_IN-60)", "locations": [{"id": ${ID_1}}], "destAddresses": ["192.168.1.25"], "nwServices": [{"id": ${ID_5}}]}
